import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage>
    with SingleTickerProviderStateMixin, WidgetsBindingObserver {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  List<CurrencyModel> _allCurrencies = [];

  int _currentPage = 0;
  bool _hasMore = true;

  String _currentFilterQuery = '';

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _initAnimation();
    _refreshList();
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  Future<void> _fetchPage(int page) async {
    final repository = context.read<CurrencyRepository>();

    if (!mounted) return;

    CurrencyPage response;
    try {
      response = await repository.fetchRates(CurrencyPageRequest(page: page, pageSize: 20));
    } catch (e) {
      return;
    }

    if (!mounted) return;

    setState(() {
      if (page == 0) {
        _allCurrencies = response.items;
      } else {
        _allCurrencies.addAll(response.items);
      }

      _currentPage = page;
      _hasMore = response.hasMore;

      _filteredCurrenciesNotifier.value = _applyFilter(_allCurrencies);

      repository.saveCurrencyList(_allCurrencies);
    });
  }

  void _loadMore() {
    if (!_hasMore) return;
    _fetchPage(_currentPage + 1);
  }

  List<CurrencyModel> _applyFilter(List<CurrencyModel> currencies) {
    final String lowerQuery = _currentFilterQuery.toLowerCase();
    if (lowerQuery.isEmpty) return currencies;
    return currencies.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) ||
          currency.symbol.toLowerCase().contains(lowerQuery);
    }).toList(growable: false);
  }

  void _filterCurrencies(String query) {
    _currentFilterQuery = query;
    _filteredCurrenciesNotifier.value = _applyFilter(_allCurrencies);
  }

  Future<void> _refreshList() async {
    setState(() {
      _currentPage = 0;
      _hasMore = true;
      _allCurrencies = [];
      _currentFilterQuery = '';
      _filteredCurrenciesNotifier.value = const <CurrencyModel>[];
    });

    await _fetchPage(0);
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed && mounted) {
      _refreshList();
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: Column(
        children: [
          Padding(
            padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
            child: SearchView(onChanged: _filterCurrencies),
          ),
          Expanded(
            child: ValueListenableBuilder<List<CurrencyModel>>(
              valueListenable: _filteredCurrenciesNotifier,
              builder: (BuildContext context, List<CurrencyModel> listData, _) {
                return ListView.builder(
                  itemCount: listData.length + (_hasMore ? 1 : 0),
                  itemBuilder: (BuildContext context, int index) {
                    if (index >= listData.length) {
                      return Center(
                        child: Padding(
                          padding: const EdgeInsets.all(16.0),
                          child: TextButton(
                            onPressed: _hasMore ? _loadMore : null,
                            child: Text(context.loc.showMore),
                          ),
                        ),
                      );
                    }

                    final CurrencyModel currency = listData[index];

                    return Padding(
                      key: ValueKey(currency.id),
                      padding: index == 0
                          ? const EdgeInsets.only(top: 20)
                          : const EdgeInsets.only(top: 10),
                      child: CurrencyCard(model: currency),
                    );
                  },
                  padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                );
              },
            ),
          ),
        ],
      ),
    );
  }
}
```

Но здесь есть проблема: при первом запуске `_refreshList()` вызывает `setState(() { ... })` затем `await _fetchPage(0)`. В `_fetchPage` снова вызывается `setState`. Это нормально.

НО! Проблема с тестами - они не будут ждать завершения асинхронной загрузки. В оригинальном коде FutureBuilder возвращал snapshot.data, и pumpAndSettle ждал settle future. Здесь у нас нет FutureBuilder - данные приходят через notifier.

