1: import 'package:mad_flutter_practicum/app/app.dart';
2: import 'package:mad_flutter_practicum/domain/domain.dart';
3: 
4: import 'widgets/widgets.dart';
5: 
6: class CurrencyListPage extends StatefulWidget {
7:   const CurrencyListPage({super.key});
8: 
9:   @override
10:   State<CurrencyListPage> createState() => _CurrencyListPageState();
11: }
12: 
13: class _CurrencyListPageState extends State<CurrencyListPage>
14:     with SingleTickerProviderStateMixin, WidgetsBindingObserver {
15:   late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;
16: 
17:   late final AnimationController _fadeController;
18: 
19:   List<CurrencyModel> _allCurrencies = [];
20: 
21:   int _currentPage = 0;
22:   bool _hasMore = true;
23: 
24:   String _currentFilterQuery = '';
25: 
26:   @override
27:   void initState() {
28:     super.initState();
29:     WidgetsBinding.instance.addObserver(this);
30:     _initAnimation();
31:     _refreshList();
32:   }
33: 
34:   @override
35:   void dispose() {
36:     WidgetsBinding.instance.removeObserver(this);
37:     _filteredCurrenciesNotifier.dispose();
38:     _fadeController.dispose();
39:     super.dispose();
40:   }
41: 
42:   Future<void> _fetchPage(int page) async {
43:     final repository = context.read<CurrencyRepository>();
44: 
45:     CurrencyPage response;
46:     try {
47:       response = await repository.fetchRates(
48:         CurrencyPageRequest(page: page, pageSize: 20),
49:       );
50:     } catch (e) {
51:       return;
52:     }
53: 
54:     if (!mounted) return;
55: 
56:     setState(() {
57:       if (page == 0) {
58:         _allCurrencies = response.items;
59:       } else {
60:         _allCurrencies.addAll(response.items);
61:       }
62: 
63:       _currentPage = page;
64:       _hasMore = response.hasMore;
65: 
66:       _filteredCurrenciesNotifier.value = _applyFilter(_allCurrencies);
67: 
68:       repository.saveCurrencyList(_allCurrencies);
69:     });
70:   }
71: 
72:   void _loadMore() {
73:     if (!_hasMore) return;
74:     _fetchPage(_currentPage + 1);
75:   }
76: 
77:   List<CurrencyModel> _applyFilter(List<CurrencyModel> currencies) {
78:     final String lowerQuery = _currentFilterQuery.toLowerCase();
79:     if (lowerQuery.isEmpty) return currencies;
80:     return currencies.where((CurrencyModel currency) {
81:       return currency.name.toLowerCase().contains(lowerQuery) ||
82:           currency.symbol.toLowerCase().contains(lowerQuery);
83:     }).toList(growable: false);
84:   }
85: 
86:   void _filterCurrencies(String query) {
87:     _currentFilterQuery = query;
88:     _filteredCurrenciesNotifier.value = _applyFilter(_allCurrencies);
89:   }
90: 
91:   Future<void> _refreshList() async {
92:     setState(() {
93:       _currentPage = 0;
94:       _hasMore = true;
95:       _allCurrencies = [];
96:       _currentFilterQuery = '';
97:       _filteredCurrenciesNotifier.value = const <CurrencyModel>[];
98:     });
99: 
100:     await _fetchPage(0);
101:   }
102: 
103:   @override
104:   void didChangeAppLifecycleState(AppLifecycleState state) {
105:     if (state == AppLifecycleState.resumed && mounted) {
106:       _refreshList();
107:     }
108:   }
109: 
110:   @override
111:   Widget build(BuildContext context) {
112:     return Scaffold(
113:       appBar: AppBar(title: Text(context.loc.currencyRate)),
114:       body: Column(
115:         children: [
116:           Padding(
117:             padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
118:             child: SearchView(onChanged: _filterCurrencies),
119:           ),
120:           Expanded(
121:             child: ValueListenableBuilder<List<CurrencyModel>>(
122:               valueListenable: _filteredCurrenciesNotifier,
123:               builder: (BuildContext context, List<CurrencyModel> listData, _) {
124:                 return ListView.builder(
125:                   itemCount: listData.length + (_hasMore ? 1 : 0),
126:                   itemBuilder: (BuildContext context, int index) {
127:                     if (index >= listData.length) {
128:                       return Center(
129:                         child: Padding(
130:                           padding: const EdgeInsets.all(16.0),
131:                           child: TextButton(
132:                             onPressed: _hasMore ? _loadMore : null,
133:                             child: Text(context.loc.showMore),
134:                           ),
135:                         ),
136:                       );
137:                     }
138: 
139:                     final CurrencyModel currency = listData[index];
140: 
141:                     return Padding(
142:                       key: ValueKey(currency.id),
143:                       padding: index == 0
144:                           ? const EdgeInsets.only(top: 20)
145:                           : const EdgeInsets.only(top: 10),
146:                       child: CurrencyCard(model: currency),
147:                     );
148:                   },
149:                   padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
150:                 );
151:               },
152:             ),
153:           ),
154:         ],
155:       ),
156:     );
157:   }
158: }

